Extract the values from this document as JSON conforming exactly to this schema. Use null for fields not present on the page. Output only JSON.

Schema:
{
  "type": "object",
  "properties": {
    "title": {
      "type": "string",
      "description": "Document title as printed"
    },
    "carrier": {
      "type": "string",
      "description": "Carrier whose logo appears on the invoice"
    },
    "documentNumber": {
      "type": "string",
      "description": "Unique identifier for the invoice"
    },
    "clientNumber": {
      "type": "string",
      "description": "Unique identifier for the client"
    },
    "issueDate": {
      "type": "string",
      "description": "Date the invoice was issued"
    },
    "page": {
      "type": "string",
      "description": "Page indicator in the header block"
    },
    "pageFooter": {
      "type": "string",
      "description": "Page indicator printed at the foot of the page"
    },
    "shipments": {
      "type": "array",
      "description": "Every shipment row printed in the table, in page order",
