              "company": {
                "type": "string"
              },
              "address": {
                "type": "string"
              },
              "city": {
                "type": "string"
              },
              "zipCode": {
                "type": "string"
              }
            }
          },
          "typeOfService": {
            "type": "string"
          },
          "weightInKg": {
            "type": "number"
          },
          "numberOfShipments": {
            "type": "number"
          },
          "baseCharge": {
            "type": "number"
          },
          "additionalCharges": {
            "type": "array",
