                "grossValue": {
                  "type": "number"
                }
              }
            }
          }
        }
      }
    },
    "mostRecentShipment": {
      "type": "object",
      "required": [
        "shipmentNumber"
      ],
      "description": "Shipment with the most recent date (closest to today's date), always the last item in the list",
      "properties": {
        "sender": {
          "type": "object",
          "required": [
            "company"
          ],
          "properties": {
            "city": {
              "type": "string",
              "description": "City of the sender as it appears, excluding zip code"
            },
            "address": {
              "type": "string",
              "description": "Street address of the sender as it appears, only including number and street"
            },
            "company": {
              "type": "string",
              "description": "Sender's company name as it appears"
            }
          }
        },
        "recipient": {
          "type": "object",
